def tau(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count

def f(x):
    # The number of such y's is (tau(x^2) - 1) / 2
    x_squared = x * x
    tau_x2 = tau(x_squared)
    return (tau_x2 - 1) // 2

